  logic [3:0] wr_ptr [M_COUNT];
  logic [3:0] rd_ptr [M_COUNT];
  logic [4:0] cnt [M_COUNT];
  logic own_v [M_COUNT];
  logic [SW-1:0] own [M_COUNT];
  logic [SW-1:0] rr [M_COUNT];
  logic acc_m [M_COUNT];
  logic [SW-1:0] acc_src [M_COUNT];
  logic pop [M_COUNT];

  int unsigned m;
  int unsigned s;
  int unsigned k;
  logic [SW-1:0] sidx;
  logic [SW-1:0] pick;
  logic found;
  logic [DEST_W-1:0] ds;

  always_comb begin
    for (m = 0; m < M_COUNT; m++) begin
      pop[m] = (cnt[m] != 5'd0) && m_ready_i[m];
      acc_m[m] = 1'b0;
      acc_src[m] = '0;
