      for (m = 0; m < M_COUNT; m++) begin
        wr_ptr[m] <= 4'd0;
        rd_ptr[m] <= 4'd0;
        cnt[m] <= 5'd0;
        own_v[m] <= 1'b0;
        own[m] <= '0;
        rr[m] <= '0;
      end
    end else begin
      for (m = 0; m < M_COUNT; m++) begin
        if (acc_m[m]) begin
          mem[m][wr_ptr[m]] <= {s_last_i[acc_src[m]],
                                s_keep_i[acc_src[m]*KEEP_W +: KEEP_W],
                                s_data_i[acc_src[m]*DATA_W +: DATA_W]};
          wr_ptr[m] <= wr_ptr[m] + 4'd1;
        end
        if (pop[m]) rd_ptr[m] <= rd_ptr[m] + 4'd1;
        cnt[m] <= cnt[m] + (acc_m[m] ? 5'd1 : 5'd0) - (pop[m] ? 5'd1 : 5'd0);
        if (!own_v[m] && acc_m[m]) begin
          own_v[m] <= 1'b1;
          own[m] <= acc_src[m];
        end
        if (own_v[m] && acc_m[m] && s_last_i[acc_src[m]]) begin
          own_v[m] <= 1'b0;
          rr[m] <= acc_src[m] + SW'(1);
        end
      end
    end
  end
endmodule
